const test=require('node:test');
const assert=require('node:assert/strict');
const C=require('../core.js');

// An actual winning route generated by deterministic beam-search, then captured
// as a fixed regression witness. All attacks, movement, relic choices, and
// end-turn resolutions go through the public reducer; no state edits/cheats.
const WINNING_RUN=[
  {actions:['Sskitter-a','MN','AN','E','ME','Swatcher-a','Swatcher-a','E','MN','AE','Sskitter-b'],relic:'brightsteel'},
  {actions:['Sskitter-a','AN','E','ME','ME','Swatcher-a','E','AE','Sskitter-b'],relic:'ashward'},
  {actions:['AN','Swatcher-a','E','AE','Sskitter-a','E','MN','E','MS','ME','Sskitter-b','E','AN','E','ME','ME','E','ME','ME','Swatcher-b'],relic:'longwick'},
  {actions:['Sskitter-a','MN','MN','E','AN','ME','Swatcher-a','E','MN','AE','Sskitter-b'],relic:'starheart'},
  {actions:['Sskitter-a','AN','Swatcher-b','E','MN','E','MN','MN','E','MN','AE','Swatcher-a'],relic:'pilgrim'},
  {actions:['MN','MN','Sheart-a','E','Sheart-a','Sheart-a','E','MS','MS','Sskitter-a']}
];
const decode=(str)=>str==='E'?{type:'END_TURN'}:
  str==='L'?{type:'TOGGLE_LANTERN'}:
  str[0]==='M'?{type:'MOVE',direction:str.slice(1)}:
  str[0]==='A'?{type:'AIM',direction:str.slice(1)}:
  {type:'STRIKE',targetId:str.slice(1)};

test('full six-chamber campaign has a real, unassisted legal winning route',()=>{
 let state=C.newGame(),commands=0;
 for(let i=0;i<WINNING_RUN.length;i++){
   const room=WINNING_RUN[i];
   assert.equal(state.roomIndex,i);
   assert.equal(C.loadable(state),true);
   for(const code of room.actions){
     const action=decode(code);
     const before=JSON.stringify(state);
     if(action.type==='END_TURN'){
       const expected=C.preview(state);
       const result=C.reducer(state,action);
       assert.deepEqual(result.state,expected.after,'preview must match real phase');
       assert.deepEqual(result.events,expected.events,'preview events must match');
       state=result.state;
     }else{
       const result=C.reducer(state,action);
       assert.equal(result.changed,true,'illegal action in room '+(i+1)+': '+code);
       assert.notEqual(JSON.stringify(result.state),before);
       state=result.state;
     }
     commands++;
     if(state.phase==='player'||state.phase==='reward')assert.equal(C.loadable(state),true);
     assert.ok(state.player.hp>0);
   }
   assert.equal(state.phase,i===5?'won':'reward','room '+(i+1));
   if(i<5){
     const chosen=C.reducer(state,{type:'CHOOSE_RELIC',id:room.relic});
     assert.equal(chosen.changed,true);
     state=chosen.state;
     assert.equal(state.roomIndex,i+1);
   }
 }
 assert.equal(state.phase,'won');
 assert.equal(state.player.hp,7);
 assert.equal(state.turn,18);
 assert.ok(commands>60);
});
